WITH inner_cte1 AS ( SELECT t0.TERM_PARAMETER, t0.TERM_CODE, t1.ACADEMIC_YEAR, t2.DEPARTMENT_NAME, SUM(t1.ACADEMIC_YEAR) OVER (PARTITION BY t2.DEPARTMENT_NAME ORDER BY t1.ACADEMIC_YEAR) AS window_column FROM ACADEMIC_TERM_PARAMETER t0 JOIN ACADEMIC_TERMS t1 ON t0.TERM_CODE = t1.TERM_CODE JOIN COURSE_CATALOG_SUBJECT_OFFERED t2 ON t1.TERM_CODE = t2.EFFECTIVE_TERM_CODE WHERE t0.TERM_INDICATOR = 'C' ), DeptCounts AS ( SELECT DEPARTMENT_NAME, COUNT(*) AS subject_count FROM COURSE_CATALOG_SUBJECT_OFFERED WHERE EFFECTIVE_TERM_CODE IN ( SELECT TERM_CODE FROM ACADEMIC_TERM_PARAMETER WHERE TERM_INDICATOR = 'C' ) GROUP BY DEPARTMENT_NAME HAVING COUNT(*) >= 3 ), cte1_result AS ( SELECT icte.TERM_PARAMETER, icte.TERM_CODE, icte.ACADEMIC_YEAR, icte.DEPARTMENT_NAME, icte.window_column FROM inner_cte1 icte JOIN DeptCounts dc ON icte.DEPARTMENT_NAME = dc.DEPARTMENT_NAME ), inner_cte2 AS ( SELECT d.DEPARTMENT_NAME, AVG(s.TOTAL_UNITS) AS avg_total_units, STDDEV(s.TOTAL_UNITS) AS stddev_total_units FROM SIS_DEPARTMENT d JOIN SUBJECT_OFFERED_SUMMARY s ON d.DEPARTMENT_CODE = s.OFFER_DEPT_CODE WHERE s.TOTAL_UNITS > 0 AND s.NUM_ENROLLED_STUDENTS >= 1 GROUP BY d.DEPARTMENT_NAME ), cte2_result AS ( SELECT inner_cte2.DEPARTMENT_NAME, inner_cte2.avg_total_units, inner_cte2.stddev_total_units, CASE WHEN inner_cte2.stddev_total_units > inner_cte2.avg_total_units * 1.2 THEN 'HIGH_VARIANCE' WHEN inner_cte2.stddev_total_units < inner_cte2.avg_total_units * 0.8 THEN 'LOW_VARIANCE' ELSE 'AVERAGE_VARIANCE' END AS variance_category FROM inner_cte2 ) SELECT c1.TERM_PARAMETER, c1.TERM_CODE, c1.ACADEMIC_YEAR, c1.DEPARTMENT_NAME, c1.window_column, c2.avg_total_units, c2.stddev_total_units, c2.variance_category FROM cte1_result c1 JOIN cte2_result c2 ON c1.DEPARTMENT_NAME = c2.DEPARTMENT_NAME ORDER BY c1.DEPARTMENT_NAME, c1.ACADEMIC_YEAR;